import math

def S_fast(n):
    if n <= 5:
        return None
    divs_gt1 = set()
    for d in range(2, int(math.isqrt(n)) + 1):
        if n % d == 0:
            divs_gt1.add(d)
            divs_gt1.add(n // d)
    divs_gt1 = sorted(divs_gt1)
    if len(divs_gt1) < 3:
        return None
    d1, d2, d3 = divs_gt1[0], divs_gt1[1], divs_gt1[2]
    return n // d1 + n // d2 + n // d3

# Find the exception: N with 6|N, 4∤N, 5∤N but S(N) != N
for n in range(6, 10001):
    if n % 6 == 0 and n % 4 != 0 and n % 5 != 0:
        s = S_fast(n)
        if s != n:
            print(f"Exception: N={n}, S(N)={s}")
            # Check divisors
            divs_gt1 = set()
            for d in range(2, int(math.isqrt(n)) + 1):
                if n % d == 0:
                    divs_gt1.add(d)
                    divs_gt1.add(n // d)
            divs_gt1 = sorted(divs_gt1)
            print(f"  Divisors > 1: {divs_gt1[:10]}...")
            print(f"  Three smallest: {divs_gt1[:3]}")

# Also check: are there valid values with 5|N?
def check_seq(a1, max_steps=300):
    a = a1
    for _ in range(max_steps):
        s = S_fast(a)
        if s is None:
            return False
        if s == a:
            return True
        a = s
    return None

valid_5 = []
for n in range(6, 10001):
    if n % 5 == 0:
        r = check_seq(n)
        if r:
            valid_5.append(n)
print(f"\nValid values with 5|N in [6,10000]: {valid_5}")

# Check: any valid value not divisible by 6?
valid_not6 = []
for n in range(6, 10001):
    if n % 6 != 0:
        r = check_seq(n)
        if r:
            valid_not6.append(n)
print(f"Valid values with 6∤N in [6,10000]: {valid_not6}")
